import { hydrateOutlineSettings } from '@/outline/settings';
import { bindOutlineLifecycle, refreshOutlineInjection } from '@/outline/service';
import { bindOutlineProgress } from '@/outline/progress';
import { hydrateWorldbookSettings } from '@/worldbook/settings';
import { bindWorldbookLifecycle } from '@/worldbook/service';
import { hydrateNotesSettings } from '@/notes/settings';
import { bindNotesLifecycle, refreshNotesInjection } from '@/notes/service';
import { apiSettings, hydrateSettings } from '@/api/settings';
import { bindEngine, handleGenerationIntercept } from '@/memory/engine';
import { bindBacklogNoticeCleanup, stripBacklogNoticesFromPrompt } from '@/backlogNotice';
import { recallStopSignal, runVectorRecall, shouldRecallForType } from '@/memory/vector/recall';
import { recallDebugWrites } from '@/memory/vector/debug';
import { armFloorRecall, beginGenerationRecall, bindFloorRecall } from '@/memory/vector/floorRecall';
import { bindContinuityNote, prepareContinuityNote } from '@/memory/continuity';
import { refreshInjection } from '@/memory/inject';
import { syncTimeTagRegex } from '@/memory/timeTag';
import { bindChatLifecycle } from '@/memory/store';
import { checkForUpdate } from '@/memory/update';
import App from '@/App.vue';
import { vAutosize } from '@/directives/autosize';
import { injectMenuButton } from '@/menu';
import { syncTopBarButton } from '@/topbar';
import { syncQuickReplyButton } from '@/quickReply';
import { syncRecallQuickReply } from '@/recallQuickReply';
import { bindFloorPanel } from '@/floorPanel';
import { bindNotesPanel } from '@/notesPanel';
import { registerPublicInterface } from '@/public/register';
import { ui } from '@/state/ui';
import { guardEditableArrowKeys } from '@/st/keyboard';
import { versionedAssetUrl } from '@/version';
import { watch } from 'vue';
// 这两行让 Vite 把全局样式打进 dist/index.css(随后注入 shadow root)
import '@/styles/base.css';
import '@/styles/theme.css';
import { createApp } from 'vue';

const HOST_ID = 'bbs-app-host';

/**
 * 生成拦截器:ST 在每次生成前会 await 调用 manifest.generate_interceptor 指名的全局函数,
 * 签名 (chat, contextSize, abort, type),调 abort(true) 即中止本次生成。
 * 这里委托给引擎判断「积压楼层过多」并按需拦截 + 插提示楼。挂在 globalThis 上供 ST 找到。
 */
(globalThis as Record<string, unknown>).bbs_generateInterceptor = async (
  chat: unknown,
  _contextSize: number,
  abort: (immediately: boolean) => void,
  type: string | undefined,
): Promise<void> => {
  try {
    // 「本次生成已拦截」提示只给用户看:从这次请求的消息副本里去掉,不发给正文模型(聊天本身不改)
    stripBacklogNoticesFromPrompt(chat);
    // 作废上一轮没用上的召回登记(楼层面板的召回记录只认本次生成)
    beginGenerationRecall(type);
    // 用户选过「提醒正文模型」的记录冲突:本次生成注入一次
    prepareContinuityNote(type);
    // 先走积压拦截:返回 true = 已 abort 本次生成,无需召回(生成不会发生)。
    refreshNotesInjection();
    refreshOutlineInjection();
    const intercepted = await handleGenerationIntercept(type, abort);
    // 放行且该类型需要召回 → 阻塞式向量召回(写注入槽后再放行生成)。
    // 召回内部自带向量开关/可用性判断,失败静默降级,绝不影响生成。
    // 召回期间监听「停止生成」:用户点停止即取消召回,不必等各请求超时。
    if (!intercepted && shouldRecallForType(type)) {
      const writes = recallDebugWrites();
      const stop = recallStopSignal();
      try {
        await runVectorRecall(stop.signal);
      } finally {
        stop.dispose();
      }
      // 召回结果登记给这次生成的回复,回复到达时写进那一楼(供楼层面板显示)
      armFloorRecall(type, writes);
    }
  } catch (e) {
    console.error('[棱镜宝书] 生成拦截器异常(放行本次生成)', e);
  }
};

/**
 * 可继承的排版属性——shadow DOM 不隔离继承,这些会透过 host 从 ST 漏进来。
 * 在 host 上用内联 !important 钉死,从根上切断继承链。
 */
const INHERITED_RESET: Record<string, string> = {
  'font-family':
    "'MiSans','HarmonyOS Sans SC','PingFang SC','Microsoft YaHei',-apple-system,BlinkMacSystemFont,'Segoe UI','Inter',system-ui,sans-serif",
  'font-size': '14px',
  'font-weight': '400',
  'font-style': 'normal',
  'font-variant': 'normal',
  'line-height': '1.6',
  'letter-spacing': 'normal',
  'word-spacing': 'normal',
  'text-align': 'left',
  'text-transform': 'none',
  'text-indent': '0',
  'text-shadow': 'none',
  'white-space': 'normal',
  color: '#1c242c',
  direction: 'ltr',
};

function mount() {
  // host 元素留在 ST 的 light DOM,Vue 应用整体活在它的 shadow root 里。
  let host = document.getElementById(HOST_ID);
  if (!host) {
    host = document.createElement('div');
    host.id = HOST_ID;
    document.body.appendChild(host);
  }

  // host 不参与布局(窗口内部用 fixed 定位),并切断继承
  host.style.setProperty('display', 'contents', 'important');
  for (const [prop, value] of Object.entries(INHERITED_RESET)) {
    host.style.setProperty(prop, value, 'important');
  }

  const shadow = host.shadowRoot ?? host.attachShadow({ mode: 'open' });
  shadow.textContent = '';
  guardEditableArrowKeys(shadow);

  // 把我们构建出的 dist/index.css 以 <link> 注入 shadow root——
  // 这样样式只在这棵 shadow 树内生效,ST 全局样式进不来,我们的也出不去。
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  // index.js 与 index.css 在 dist 同级,据当前模块 URL 推导,部署路径无关。
  link.href = versionedAssetUrl('./index.css', import.meta.url);
  shadow.appendChild(link);

  const container = document.createElement('div');
  shadow.appendChild(container);

  const app = createApp(App);
  app.directive('autosize', vAutosize);
  app.mount(container);

  $(window).on('pagehide', () => app.unmount());
}

$(() => {
  mount();
  injectMenuButton();
  // 顶栏快速打开按钮:按开关注入/移除。watch 在开关变化(含 hydrate 回灌真值)时同步。
  syncTopBarButton(ui.showTopBar);
  watch(
    () => ui.showTopBar,
    on => syncTopBarButton(on),
  );
  // 聊天框快速回复式按钮:同上范式
  syncQuickReplyButton(ui.showQuickReply);
  watch(
    () => ui.showQuickReply,
    on => syncQuickReplyButton(on),
  );
  // 快捷回复栏的「召回」按钮:开了向量记忆、且设置里没关掉才显示
  const recallButtonWanted = () => ui.showRecallQuickReply && apiSettings.vector.enabled;
  syncRecallQuickReply(recallButtonWanted());
  watch(recallButtonWanted, on => syncRecallQuickReply(on));
  // 记忆系统:等 ST 的 getContext 就绪后再绑定(加载顺序不确定时轮询)
  bindMemoryWhenReady();
});

function bindMemoryWhenReady(attempt = 0) {
  if (window.SillyTavern?.getContext) {
    try {
      console.log('[棱镜宝书] 启动链开始绑定(getContext 就绪)');
      // 设置先 hydrate:从 extension_settings 载入(或从旧 localStorage 迁移),之后才跨设备同步
      hydrateSettings();
      bindChatLifecycle();
      hydrateNotesSettings();
      bindNotesLifecycle();
      hydrateOutlineSettings();
      bindOutlineLifecycle();
      // 规划推进条件:回复到达时按设置自动检查(默认关),切聊天清空结果
      bindOutlineProgress();
      // 世界书建议:载入设置与本聊天的建议;自动建议默认关,开启后每隔 N 个 AI 楼层在正文生成结束后运行
      hydrateWorldbookSettings();
      bindWorldbookLifecycle();
      // 公共读取接口不依赖记忆引擎开关；聊天载入后立即暴露，供其它插件/脚本读取。
      void registerPublicInterface();
      bindEngine();
      // 缺摘要的楼层补齐后,自动删除聊天末尾的「本次生成已拦截」提示
      bindBacklogNoticeCleanup();
      // 时间标签:按开关注册/移除 ST 隐藏正则(幂等;开关变化的后续同步在 bindEngine 的 watch 里)
      syncTimeTagRegex();
      // 首屏:把当前聊天已有的记忆挂上注入
      refreshInjection();
      // 楼内摘要锚点:按设置开关注入(bindFloorPanel 内 watch 开关 + 主题,immediate 首次同步)
      bindFloorPanel();
      // 聊天里的札记卡片:启用双子札记且札记页里「在聊天中显示札记」打开时,挂在最新正文楼层和有札记的楼层下方
      bindNotesPanel();
      // 回复到达时记下生成前召回了什么(只在启用楼层面板时写入)
      bindFloorRecall();
      // 记录冲突的连续性提醒:回复到达后标为已提醒
      bindContinuityNote();
      // 后台检测更新(实时比对本地/远端 manifest 版本;失败静默,不阻断启动)
      void checkForUpdate();
      console.log('[棱镜宝书] 启动链绑定完成');
    } catch (e) {
      console.error('[棱镜宝书] 记忆系统绑定失败', e);
    }
    return;
  }
  if (attempt > 40) return; // 最多约 20s
  setTimeout(() => bindMemoryWhenReady(attempt + 1), 500);
}
